#!/usr/bin/env python3
"""Generate native Froggy telemetry records and the integration ledger."""

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
REPOSITORY = ROOT.parents[1]
MANIFEST = ROOT / "jericho" / "froggy_bindings.json"
NATIVE_OUTPUT = ROOT / "frotz" / "src" / "games" / "froggy_generated.inc"
LEDGER = REPOSITORY / "docs" / "jericho-integrations.md"
LEDGER_START = "<!-- generated batch start -->"
LEDGER_END = "<!-- generated batch end -->"


def c_string(value):
    return json.dumps(value, ensure_ascii=True)


def generate_native(games):
    lines = ["/* Generated by scripts/generate_froggy_registry.py. */"]
    for game in games.values():
        native = game["native"]
        lines.extend(
            [
                "  {",
                f"    {c_string(game['md5'].upper())},",
                f"    {c_string(native['victory_text'])}, "
                f"{c_string(native.get('loss_text', '*** You have died ***'))},",
                f"    {native['player_object']}, {native['moves_address']}, "
                f"{native.get('moves_base', 0)}, {native.get('score_address', -1)}, "
                f"{native.get('score_base', 0)}, {native['max_score']}, "
                f"{native['world_objects']}, {c_string(native['player_name'])},",
                f"    {native.get('location_object', 0)}, "
                f"{c_string(native.get('location_name', ''))}, "
                f"{native.get('victory_moves', 0)}",
                "  },",
            ]
        )
    NATIVE_OUTPUT.write_text("\n".join(lines) + "\n")


def generate_ledger(games):
    document = LEDGER.read_text()
    before, remainder = document.split(LEDGER_START, 1)
    _, after = remainder.split(LEDGER_END, 1)
    rows = [
        "",
        "| Game key | ROM | MD5 | Score model | Loss | World objects | Validation | Commit |",
        "| --- | --- | --- | --- | --- | ---: | --- | --- |",
    ]
    for game in games.values():
        native = game["native"]
        validation = game["validation"]
        score_model = (
            f"authored `{validation['score']}/{native['max_score']}`"
            if native.get("score_address", -1) >= 0
            else f"synthetic `{native['max_score']}/{native['max_score']}`"
        )
        loss = "authored" if validation.get("loss_commands") else "no authored loss"
        rows.append(
            f"| `{game['key']}` | `{game['rom']}` | `{game['md5']}` | "
            f"{score_model} | {loss} | {native['world_objects']} | "
            "native + TALE | per-game checkpoint |"
        )
    replacement = "\n".join(rows) + ("\n" if games else "")
    LEDGER.write_text(
        before + LEDGER_START + replacement + LEDGER_END + after
    )


def main():
    games = json.loads(MANIFEST.read_text())
    for key, game in games.items():
        if key != game["key"]:
            raise ValueError(f"Manifest key {key!r} does not match game key")
        if len(game["md5"]) != 32:
            raise ValueError(f"{key}: invalid MD5")
    generate_native(games)
    generate_ledger(games)


if __name__ == "__main__":
    main()
